        c = new Cooler();
    }

    function _run(uint256 amount, uint256 rate) internal {
        uint256 expected = (amount * ((rate * 0) / 365 days)) / 1e18;
        uint256 result;
        try c.interestFor(amount, rate, 0) returns (uint256 __r) { result = __r; } catch { return; }
        assertTrue(result == expected);
    }

    function testFuzz_run(uint256 amount, uint256 rate) public {
